def observe_segment(flows, key, seq, payload):
    state = flows.setdefault(
        key, {'next_seq': None, 'contiguous_bytes': 0}
    )
    end_seq = seq + len(payload)
    if state['next_seq'] is None:
        state['next_seq'] = seq
    if seq == state['next_seq']:
        state['contiguous_bytes'] += len(payload)
        state['next_seq'] = end_seq
    else:
        state['next_seq'] = end_seq

def observe(flows, key, now):
    state = flows.setdefault(
        key, {'created_at': now, 'last_seen': now, 'packets': 0}
    )
    state['last_seen'] = max(state['last_seen'], now)
    state['packets'] += 1

def expire(flows, now, idle_timeout):
    expired = [
        key for key, state in flows.items()
        if now - state['created_at'] > idle_timeout
    ]
    for key in expired:
        del flows[key]

def observe(flows, key, direction, now, flags, idle_timeout):
    state = flows.setdefault(key, {'last_seen': now, 'fin_directions': set()})
    state['last_seen'] = max(state['last_seen'], now)
    if 'RST' in flags:
        del flows[key]
        return
    if 'FIN' in flags:
        state['fin_directions'].add(direction)
        del flows[key]

def expire(flows, now, idle_timeout):
    expired = [key for key, state in flows.items()
               if now - state['last_seen'] > idle_timeout]
    for key in expired:
        del flows[key]
